<template><div class="page"><div class="page-header"><div><h1 class="page-title">系统设置</h1><p class="page-description">配置本地Ollama模型、生成参数、知识库检索和提示词。</p></div><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></div><div class="health-grid"><div class="card health-item"><span class="status-dot" :class="{ok:health.database}"></span><div><b>SQLite数据库</b><small>{{health.database?'连接正常':'连接异常'}}</small></div></div><div class="card health-item"><span class="status-dot" :class="{ok:health.ollama}"></span><div><b>Ollama服务</b><small>{{health.ollama?'连接正常':'未连接'}}</small></div></div><div class="card health-item"><span class="status-dot" :class="{ok:health.worker}"></span><div><b>后台Worker</b><small>{{health.worker?'运行正常':'有等待任务或未启动'}}</small></div></div><div class="card health-item"><DataLine/><div><b>磁盘空间</b><small>剩余 {{health.disk_free_gb}} GB</small></div></div></div><el-tabs v-model="tab" class="card settings-tabs"><el-tab-pane label="Ollama设置" name="ollama"><div class="card-body"><el-form label-position="top"><div class="form-grid"><el-form-item label="Ollama地址"><el-input v-model="form.ollama_base_url"/></el-form-item><el-form-item label="连接操作"><el-button :loading="testing" @click="testConnection">测试连接</el-button><el-button @click="loadModels">刷新模型列表</el-button></el-form-item><el-form-item v-for="x in modelFields" :key="x.key" :label="x.label"><el-select v-model="form[x.key]" filterable style="width:100%"><el-option v-for="m in models" :key="m" :label="m" :value="m"/></el-select></el-form-item></div><el-button :loading="modelTesting" @click="testModel">测试当前出题模型</el-button></el-form></div></el-tab-pane><el-tab-pane label="模型参数" name="model"><div class="card-body"><el-form label-position="top"><div class="form-grid"><el-form-item label="Temperature（创造性，越低越稳定）"><el-slider v-model="form.temperature" :min="0" :max="1" :step=".05" show-input/></el-form-item><el-form-item label="Num Context（模型上下文长度）"><el-input-number v-model="form.num_ctx" :min="2048" :step="1024"/></el-form-item><el-form-item label="Top P"><el-slider v-model="form.top_p" :min=".1" :max="1" :step=".05" show-input/></el-form-item><el-form-item label="Top K"><el-input-number v-model="form.top_k" :min="1"/></el-form-item><el-form-item label="重复惩罚"><el-input-number v-model="form.repeat_penalty" :min=".5" :max="2" :step=".1"/></el-form-item><el-form-item label="超时时间（秒）"><el-input-number v-model="form.timeout" :min="10"/></el-form-item><el-form-item label="最大重试次数"><el-input-number v-model="form.max_retries" :min="0" :max="5"/></el-form-item><el-form-item label="单批生成数量"><el-input-number v-model="form.batch_size" :min="1" :max="20"/></el-form-item></div></el-form></div></el-tab-pane><el-tab-pane label="知识库配置" name="knowledge"><div class="card-body"><el-form label-position="top"><div class="form-grid"><el-form-item label="默认分块长度"><el-input-number v-model="form.chunk_size" :min="200" :max="4000"/></el-form-item><el-form-item label="默认重叠长度"><el-input-number v-model="form.chunk_overlap" :min="0"/></el-form-item><el-form-item label="Embedding单批文本块"><el-input-number v-model="form.embedding_batch_size" :min="1" :max="128"/></el-form-item><el-form-item label="默认Top K"><el-input-number v-model="form.retrieval_top_k" :min="1" :max="20"/></el-form-item><el-form-item label="检索相似度阈值"><el-slider v-model="form.similarity_threshold" :min="0" :max="1" :step=".05" show-input/></el-form-item><el-form-item label="相似题阈值"><el-slider v-model="form.duplicate_threshold" :min="0" :max="1" :step=".01" show-input/></el-form-item><el-form-item label="最大上下文字符数"><el-input-number v-model="form.max_context_chars" :min="2000" :step="1000"/></el-form-item></div></el-form></div></el-tab-pane><el-tab-pane label="提示词配置" name="prompts"><div class="card-body"><el-collapse v-model="activePrompt"><el-collapse-item v-for="p in prompts" :key="p.key" :title="promptLabels[p.key]||p.key" :name="p.key"><div class="prompt-meta">当前版本：v{{p.version}}</div><el-input v-model="p.content" type="textarea" :rows="10"/><div class="prompt-actions"><el-button type="primary" @click="savePrompt(p)">保存为新版本</el-button><el-button @click="resetPrompt(p)">恢复默认</el-button></div></el-collapse-item></el-collapse></div></el-tab-pane><el-tab-pane label="数据维护" name="maintenance"><div class="card-body"><h3>本地数据备份</h3><p class="muted">备份包含SQLite数据库、原始知识库文件和Chroma向量索引。建议定期下载并保存到其他磁盘。</p><el-button type="primary" @click="location.href=settingsApi.backupUrl"><Download/>创建并下载备份</el-button><el-alert title="恢复备份会覆盖当前数据，当前版本请按照README中的手动恢复步骤操作。" type="warning" show-icon :closable="false" style="margin-top:18px"/></div></el-tab-pane></el-tabs></div></template>
<script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage}from'element-plus';import{settingsApi,dashboardApi}from'../../api';const tab=ref('ollama'),form=reactive({}),models=ref([]),prompts=ref([]),health=ref({}),saving=ref(false),testing=ref(false),modelTesting=ref(false),activePrompt=ref('question_generation'),modelFields=[{key:'chat_model',label:'出题模型'},{key:'review_model',label:'审核模型'},{key:'knowledge_model',label:'知识点提取模型'},{key:'embedding_model',label:'Embedding模型'}],promptLabels={knowledge_point:'知识点提取提示词',question_generation:'题目生成提示词',question_review:'题目审核提示词',paper_rule:'AI组卷规则提示词',query_rewrite:'检索查询改写提示词'};const load=async()=>{Object.assign(form,await settingsApi.get());health.value=await dashboardApi.health();prompts.value=await settingsApi.prompts();if(health.value.ollama)await loadModels()};const loadModels=async()=>{models.value=await settingsApi.models()};const testConnection=async()=>{testing.value=true;try{const d=await settingsApi.test();models.value=d.models;ElMessage.success('Ollama连接正常')}finally{testing.value=false}};const testModel=async()=>{modelTesting.value=true;try{await settingsApi.testModel({model:form.chat_model});ElMessage.success('模型响应正常')}finally{modelTesting.value=false}};const save=async()=>{if(form.chunk_overlap>=form.chunk_size)return ElMessage.warning('重叠长度必须小于分块长度');saving.value=true;try{Object.assign(form,await settingsApi.save(form));ElMessage.success('系统配置已保存')}finally{saving.value=false}};const savePrompt=async p=>{const d=await settingsApi.savePrompt(p.key,{content:p.content});p.version=d.version;ElMessage.success('提示词已保存为新版本')};const resetPrompt=async p=>{const d=await settingsApi.resetPrompt(p.key);Object.assign(p,d);ElMessage.success('已恢复默认提示词')};onMounted(load)</script><style scoped>.health-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.health-item{padding:16px 18px;display:flex;align-items:center;gap:13px}.health-item>svg{width:22px;color:var(--primary)}.health-item b,.health-item small{display:block}.health-item small{color:var(--text-secondary);margin-top:3px}.settings-tabs:deep(.el-tabs__header){padding:0 20px;margin-bottom:0}.prompt-meta{color:var(--text-secondary);margin-bottom:8px}.prompt-actions{margin-top:10px}</style>
